const getMem=()=>{try{return JSON.parse(localStorage.getItem("cvnames"))||{}}catch(x){return{}}};
const addMem=(type,n,isNew)=>{try{const m=getMem();m[type]=m[type]||[];if(!m[type].some(x=>x.toLowerCase()===n.toLowerCase()))m[type].unshift(n);localStorage.setItem("cvnames",JSON.stringify(m))}catch(x){}
 if(isNew)sbAdd(type,n)};
const localItems=(type,q)=>{const s=q.toLowerCase(),r=[];(getMem()[type]||[]).forEach(n=>n.toLowerCase().includes(s)&&r.push({n,d:t().srcMem,s:0}));
 if(type==="inst")SEED_INST.forEach(([en,bn])=>{if((en+bn).toLowerCase().includes(s))r.push({n:S.lang==="bn"?bn:en,d:t().srcList,s:1})});
 if(type==="pos"){const tk=s.split(/\s+/).filter(Boolean);SEED_POS.forEach(([en,bn])=>{const h=(en+" "+bn).toLowerCase();if(tk.every(w=>h.includes(w)))r.push({n:S.lang==="bn"?bn:en,d:t().srcPos,s:(en.toLowerCase().startsWith(s)||bn.startsWith(s))?1:1.5})})}
 if(type==='ai')TOOLS.forEach(x=>{if(x[0].toLowerCase().includes(s))r.push({n:x[0],d:catName(x[1]),s:x[0].toLowerCase().startsWith(s)?1:1.5})});
 return r};
async function webFind(type,q){const out=[];let ok=false;const jobs=[];
 jobs.push(sbFind(type,q).then(a=>{ok=true;a.forEach(n=>out.push({n,d:t().srcShared,s:-1}))}).catch(()=>{}));
 (type==="pos"||type==="ai"?[]:["en","bn"]).forEach(l=>jobs.push(fetch(`https://www.wikidata.org/w/api.php?action=wbsearchentities&search=${encodeURIComponent(q)}&language=${l}&uselang=${l}&type=item&limit=6&format=json&origin=*`,{signal:AbortSignal.timeout(6000)}).then(r=>r.json()).then(j=>{ok=true;(j.search||[]).forEach(x=>out.push({n:x.label,d:t().srcWeb+(x.description?" · "+x.description:""),s:2}))}).catch(()=>{})));
 await Promise.all(jobs);return{items:out,ok}}
const mergeNames=a=>{const seen=new Set(),o=[];a.slice().sort((x,y)=>x.s-y.s).forEach(x=>{const k=(x.n||"").toLowerCase();if(x.n&&!seen.has(k)){seen.add(k);o.push(x)}});return o.slice(0,8)};
